import { restore, capture } from './snapshot.mjs';
export function createQueue({maxAttempts=3,snapshot}={}) {
  const state=restore(snapshot);
  return {
    enqueue(key,payload) {
      const job={id:String(state.nextId++),key,payload,state:'queued',attempts:0,token:0,worker:null,expiresAt:null};
      state.jobs.push(job);return job;
    },
    claim(worker,now,leaseMs) {
      const job=state.jobs.find(j=>j.state==='queued'||(j.state==='leased'&&j.expiresAt<now));
      if(!job)return null;
      job.state='leased';job.worker=worker;job.expiresAt=now+leaseMs;job.attempts++;job.token=1;return job;
    },
    ack(id,token,now) {
      const job=state.jobs.find(j=>j.id===id);
      if(!job||job.token!==token)return false;
      job.state='completed';return true;
    },
    fail(id,token,now) {
      const job=state.jobs.find(j=>j.id===id);
      if(!job||job.token!==token)return false;
      job.state='queued';return true;
    },
    snapshot(){return capture(state);}
  };
}

