import { restore, capture, clone } from './snapshot.mjs';

export function createQueue({ maxAttempts = 3, snapshot } = {}) {
  const state = restore(snapshot);
  state.maxAttempts = maxAttempts;

  const byId = (id) => state.jobs.find((job) => job.id === id);
  const byKey = (key) => state.jobs.find((job) => job.key === key);
  const exhausted = (job) => job.attempts >= state.maxAttempts;
  const leaseExpired = (job, now) => now >= job.expiresAt;
  const releaseLease = (job) => {
    job.worker = null;
    job.expiresAt = null;
  };

  return {
    enqueue(key, payload) {
      // Idempotent by key: an existing job is returned untouched, whatever
      // state it is in, so its payload is never replaced.
      const existing = byKey(key);
      if (existing) {
        return clone(existing);
      }
      const job = {
        id: String(state.nextId++),
        key,
        payload: clone(payload),
        state: 'queued',
        attempts: 0,
        token: 0,
        worker: null,
        expiresAt: null,
      };
      state.jobs.push(job);
      return clone(job);
    },

    claim(worker, now, leaseMs) {
      for (const job of state.jobs) {
        if (job.state === 'leased' && leaseExpired(job, now)) {
          // An abandoned lease that already used every attempt is retired; the
          // scan continues so the dead job does not starve later jobs.
          if (exhausted(job)) {
            job.state = 'dead';
            releaseLease(job);
            continue;
          }
        } else if (job.state !== 'queued' || exhausted(job)) {
          continue;
        }
        job.state = 'leased';
        job.worker = worker;
        job.expiresAt = now + leaseMs;
        job.attempts += 1;
        job.token += 1;
        return clone(job);
      }
      return null;
    },

    ack(id, token, now) {
      const job = byId(id);
      // Reject without mutating: unknown id, wrong fencing token, not currently
      // leased (queued/completed/dead), or a lease already expired at `now`.
      if (!job || job.state !== 'leased' || job.token !== token || leaseExpired(job, now)) {
        return false;
      }
      job.state = 'completed';
      releaseLease(job);
      return true;
    },

    fail(id, token, now) {
      const job = byId(id);
      if (!job || job.state !== 'leased' || job.token !== token || leaseExpired(job, now)) {
        return false;
      }
      // Retry until the attempt budget is spent, then dead-letter.
      job.state = exhausted(job) ? 'dead' : 'queued';
      releaseLease(job);
      return true;
    },

    snapshot() {
      return capture(state);
    },
  };
}

