// State (de)serialization helpers for the synthetic lease queue.
//
// Every value that crosses the public API boundary is deep-copied so that
// callers, snapshots and queue internals never share mutable references.

/** Deep copy of a JSON-shaped value (objects, arrays, primitives, null). */
export function clone(value) {
  if (Array.isArray(value)) {
    return value.map(clone);
  }
  if (value !== null && typeof value === 'object') {
    const copy = {};
    for (const key of Object.keys(value)) {
      // defineProperty, not assignment: a JSON object may legitimately carry an
      // own key named "__proto__". Plain assignment would hit the inherited
      // Object.prototype setter and silently drop the key, so define every key
      // as a real own data property instead. The result stays a plain object
      // with Object.prototype as its prototype.
      Object.defineProperty(copy, key, {
        value: clone(value[key]),
        enumerable: true,
        writable: true,
        configurable: true,
      });
    }
    return copy;
  }
  return value;
}

/** Clone a restored job and make sure every documented field is present. */
function restoreJob(job) {
  const copy = clone(job);
  copy.id = String(copy.id);
  copy.state = typeof copy.state === 'string' ? copy.state : 'queued';
  copy.attempts = Number.isInteger(copy.attempts) ? copy.attempts : 0;
  copy.token = Number.isInteger(copy.token) ? copy.token : 0;
  copy.worker = copy.worker ?? null;
  copy.expiresAt = copy.expiresAt ?? null;
  return copy;
}

function highestId(jobs) {
  let highest = 0;
  for (const job of jobs) {
    if (/^[0-9]+$/.test(job.id)) {
      highest = Math.max(highest, Number(job.id));
    }
  }
  return highest;
}

/**
 * Build fresh internal state from a snapshot. Caller-owned data is cloned, so
 * mutating the input after restore cannot reach the new queue. maxAttempts is
 * intentionally absent from a snapshot; createQueue supplies it again.
 */
export function restore(snapshot) {
  const source = snapshot ?? {};
  const jobs = Array.isArray(source.jobs) ? source.jobs.map(restoreJob) : [];
  const requested = Number.isInteger(source.nextId) && source.nextId > 0 ? source.nextId : 1;
  // Keep the recorded counter, but never hand out an id an existing job owns.
  return { nextId: Math.max(requested, highestId(jobs) + 1), jobs };
}

/** Detached, JSON-compatible snapshot of the queue state. */
export function capture(state) {
  return clone({ nextId: state.nextId, jobs: state.jobs });
}

