// Regression coverage for contract edges the smoke tests do not pin down:
// idempotency across every job state, oldest-eligible selection, monotonic
// fencing across repeated expiries, expiry-driven dead-lettering, deep
// detachment, and JSON restore of order/tokens/nextId.
import {test} from 'node:test';
import assert from 'node:assert/strict';
import {createQueue} from '../src/queue.mjs';

const job = q => q.snapshot().jobs[0];

test('enqueue is idempotent across every job state and keeps the payload', () => {
  const q = createQueue({maxAttempts:2});
  const original = q.enqueue('k',{n:1});
  assert.equal(q.snapshot().nextId,2);

  // leased: the returned clone reflects the live job but never replaces it
  q.claim('w',0,5);
  assert.deepEqual(q.enqueue('k',{n:2}),{...original,state:'leased',attempts:1,token:1,worker:'w',expiresAt:5});

  // completed
  assert.equal(q.ack(original.id,1,1),true);
  assert.equal(q.enqueue('k',{n:3}).state,'completed');

  assert.equal(q.snapshot().jobs.length,1);
  assert.equal(q.snapshot().nextId,2);
  assert.equal(job(q).payload.n,1);
});

test('claim picks the oldest eligible job, looking past an active lease', () => {
  const q = createQueue();
  q.enqueue('a',{});
  q.enqueue('b',{});
  q.enqueue('c',{});
  assert.equal(q.claim('w',0,100).id,'1');
  assert.equal(q.claim('w',1,1).id,'2');
  assert.equal(q.snapshot().jobs[0].state,'leased');
  assert.equal(q.snapshot().jobs[0].worker,'w');
});

test('every reclaim raises the fencing token and invalidates older ones', () => {
  const q = createQueue();
  q.enqueue('a',{});
  const t1 = q.claim('w1',0,10);
  const t2 = q.claim('w2',10,10);
  const t3 = q.claim('w3',20,10);
  assert.deepEqual([t1.token,t2.token,t3.token],[1,2,3]);
  assert.deepEqual([t1.attempts,t2.attempts,t3.attempts],[1,2,3]);
  assert.equal(t3.expiresAt,30);

  const before = q.snapshot();
  assert.equal(q.ack('1',t1.token,20),false);
  assert.equal(q.fail('1',t2.token,20),false);
  assert.deepEqual(q.snapshot(),before);

  assert.equal(q.ack('1',t3.token,20),true);
  assert.equal(q.snapshot().jobs[0].state,'completed');
});

test('expired exhaustion dead-letters and does not starve later jobs', () => {
  const q = createQueue({maxAttempts:2});
  q.enqueue('a',{});
  q.enqueue('b',{});
  q.claim('w',0,5);
  q.claim('w',5,5);
  assert.equal(q.claim('w',10,5).id,'2');
  const dead = job(q);
  assert.equal(dead.state,'dead');
  assert.deepEqual([dead.worker,dead.expiresAt],[null,null]);
  assert.deepEqual([dead.attempts,dead.token],[2,2]);
  // the surviving job can still be reclaimed once its own lease expires
  assert.equal(q.claim('w',15,5).id,'2');
});

test('fail retries then dead-letters, and a dead key stays idempotent', () => {
  const q = createQueue({maxAttempts:2});
  q.enqueue('a',{v:1});
  const l1 = q.claim('w1',0,10);
  assert.equal(q.fail(l1.id,l1.token,1),true);
  assert.deepEqual([job(q).state,job(q).worker,job(q).expiresAt],['queued',null,null]);

  const l2 = q.claim('w2',2,10);
  assert.equal(q.fail(l2.id,l2.token,3),true);
  assert.deepEqual([job(q).state,job(q).attempts,job(q).token],['dead',2,2]);

  const again = q.enqueue('a',{v:99});
  assert.deepEqual([again.state,again.payload.v],['dead',1]);
  assert.equal(q.claim('w3',4,10),null);
});

test('snapshot and restore deep-detach nested structures in both directions', () => {
  const q = createQueue();
  const payload = {list:[{deep:[1,2]}],flag:true};
  q.enqueue('a',payload);
  payload.list[0].deep.push(3);
  assert.deepEqual(job(q).payload,{list:[{deep:[1,2]}],flag:true});

  const snap = q.snapshot();
  snap.jobs[0].payload.list[0].deep.push(9);
  snap.jobs[0].worker = 'tampered';
  assert.deepEqual(job(q).payload.list[0].deep,[1,2]);
  assert.equal(job(q).worker,null);

  const restored = createQueue({snapshot:snap});
  snap.jobs[0].payload.list[0].deep.push(7);
  assert.deepEqual(restored.snapshot().jobs[0].payload.list[0].deep,[1,2,9]);
});

test('JSON restore keeps order, nextId and tokens and continues fencing', () => {
  const q = createQueue();
  q.enqueue('a',{n:1});
  q.enqueue('b',{n:2});
  q.claim('w',0,4);

  const r = createQueue({snapshot:JSON.parse(JSON.stringify(q.snapshot()))});
  assert.deepEqual(r.snapshot(),q.snapshot());
  assert.equal(r.enqueue('b',{}).id,'2');
  assert.equal(r.enqueue('c',{}).id,'3');

  const lease = r.claim('w',4,4);
  assert.deepEqual([lease.id,lease.token,lease.attempts],['1',2,2]);
  assert.equal(r.ack('1',1,5),false);
  assert.equal(r.ack('1',2,5),true);
});

test('lease boundary rejects acks and permits reclaim at now === expiresAt', () => {
  const q = createQueue();
  q.enqueue('a',{});
  const lease = q.claim('w',0,10);
  const before = JSON.stringify(q.snapshot());
  assert.equal(q.ack(lease.id,lease.token,10),false);
  assert.equal(q.fail(lease.id,lease.token,10),false);
  assert.equal(JSON.stringify(q.snapshot()),before);

  const reclaimed = q.claim('w2',10,10);
  assert.deepEqual([reclaimed.token,reclaimed.worker,reclaimed.expiresAt],[2,'w2',20]);
});

test('ack and fail reject non-leased or unknown ids without mutation', () => {
  const q = createQueue();
  q.enqueue('a',{});
  assert.equal(q.ack('1',0,0),false);
  assert.equal(q.fail('1',0,0),false);
  const before = JSON.stringify(q.snapshot());
  assert.equal(q.ack('999',1,1),false);
  assert.equal(q.fail('999',1,1),false);
  assert.equal(JSON.stringify(q.snapshot()),before);
});

test('JSON keys literally named __proto__ survive clone, snapshot and restore', () => {
  const q = createQueue();
  const payload = JSON.parse('{"__proto__":{"flag":true},"nested":{"__proto__":{"n":2}}}');
  q.enqueue('json',payload);

  const stored = q.snapshot().jobs[0].payload;
  assert.ok(Object.prototype.hasOwnProperty.call(stored,'__proto__'));
  assert.ok(Object.prototype.hasOwnProperty.call(stored.nested,'__proto__'));
  assert.deepEqual(stored,payload);
  assert.equal(JSON.stringify(stored),JSON.stringify(payload));
  // ordinary object semantics: plain prototype, real enumerable own keys
  assert.equal(Object.getPrototypeOf(stored),Object.prototype);
  assert.deepEqual(Object.keys(stored).sort(),['__proto__','nested']);

  // detachment still holds for the special key
  payload.__proto__.flag = false;
  payload.nested.__proto__.n = 99;
  const after = q.snapshot().jobs[0].payload;
  assert.deepEqual(after.__proto__,{flag:true});
  assert.deepEqual(after.nested.__proto__,{n:2});

  // JSON restore preserves and detaches the key too
  const restored = createQueue({snapshot:JSON.parse(JSON.stringify(q.snapshot()))});
  assert.ok(Object.prototype.hasOwnProperty.call(restored.snapshot().jobs[0].payload,'__proto__'));
  assert.deepEqual(restored.snapshot().jobs[0].payload,after);

  // the detached lease handed back by claim is independent as well
  const lease = q.claim('w',0,5);
  lease.payload.nested.__proto__.n = 7;
  assert.equal(q.snapshot().jobs[0].payload.nested.__proto__.n,2);
});
